import json
from pathlib import Path


def load_payload(path):
    def _reject(value):
        raise ValueError("non-finite JSON constant: %s" % value)

    data = json.loads(Path(path).read_text(encoding="utf-8"), parse_constant=_reject)
    if not isinstance(data, (dict, list)):
        raise ValueError("top level must be object or array")
    return data

import re

_ESCAPE_RE = re.compile(r"\\(040|011|134)")
_ESCAPE_MAP = {"040": " ", "011": "\t", "134": "\\"}


def _check_contract(contract, payloads):
    if not isinstance(contract, dict):
        raise ValueError("contract must be object")
    for key in ("name", "inputs"):
        if key not in contract:
            raise ValueError("contract missing field: %s" % key)
    if not isinstance(contract["name"], str):
        raise ValueError("contract name must be string")
    if not isinstance(contract["inputs"], list):
        raise ValueError("contract inputs must be list")
    if len(payloads) != len(contract["inputs"]):
        raise ValueError("payload count mismatch")


def _unwrap(payload):
    if isinstance(payload, dict) and set(payload.keys()) == {"name", "result"}:
        return payload["result"]
    return payload


def _decode(text):
    return _ESCAPE_RE.sub(lambda m: _ESCAPE_MAP[m.group(1)], text)


def _options(options_text):
    return ",".join(sorted(set(options_text.split(","))))


def transform(payloads, contract):
    _check_contract(contract, payloads)
    data = _unwrap(payloads[0])
    if not isinstance(data, dict) or "fstab" not in data:
        raise ValueError("missing fstab input")
    text = data["fstab"]
    if not isinstance(text, str):
        raise ValueError("fstab must be string")
    records = []
    for raw in text.split("\n"):
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        columns = line.split()
        if not 4 <= len(columns) <= 6:
            raise ValueError("fstab line must have 4 to 6 columns: %r" % line)
        device, mount, fstype, options = (_decode(c) for c in columns[:4])
        records.append({
            "device": device,
            "mount": mount,
            "fstype": fstype,
            "options": _options(options),
        })
    return {"name": contract["name"], "result": {"records": records}}

