_KEYS = ("dev", "vfs", "options")


def _check_contract(contract, payloads):
    if not isinstance(contract, dict):
        raise ValueError("contract must be object")
    for key in ("name", "inputs"):
        if key not in contract:
            raise ValueError("contract missing field: %s" % key)
    if not isinstance(contract["name"], str):
        raise ValueError("contract name must be string")
    if not isinstance(contract["inputs"], list):
        raise ValueError("contract inputs must be list")
    if len(payloads) != len(contract["inputs"]):
        raise ValueError("payload count mismatch")


def _unwrap(payload):
    if isinstance(payload, dict) and set(payload.keys()) == {"name", "result"}:
        return payload["result"]
    return payload


def _options(options_text):
    return ",".join(sorted(set(options_text.split(","))))


def transform(payloads, contract):
    _check_contract(contract, payloads)
    data = _unwrap(payloads[0])
    if not isinstance(data, dict) or "aix" not in data:
        raise ValueError("missing aix input")
    text = data["aix"]
    if not isinstance(text, str):
        raise ValueError("aix must be string")
    records = []

    def finish(section):
        if section is None:
            return
        mount, attrs = section
        if "dev" not in attrs:
            raise ValueError("section %r missing dev" % mount)
        records.append({
            "device": attrs["dev"],
            "mount": mount,
            "fstype": attrs.get("vfs", "jfs2"),
            "options": _options(attrs.get("options", "rw")),
        })

    section = None
    for raw in text.split("\n"):
        stripped = raw.strip()
        if not stripped or stripped.startswith("#"):
            continue
        if raw[:1].isspace():
            if section is None:
                raise ValueError("attribute before section header")
            if "=" not in stripped:
                raise ValueError("bad attribute line: %r" % stripped)
            key, value = stripped.split("=", 1)
            key = key.strip()
            value = value.strip()
            if key not in _KEYS:
                raise ValueError("unknown key: %r" % key)
            if key in section[1]:
                raise ValueError("duplicate key: %r" % key)
            section[1][key] = value
        else:
            finish(section)
            if ":" not in stripped:
                raise ValueError("bad section header: %r" % stripped)
            mount = stripped.split(":", 1)[0].strip()
            if not mount:
                raise ValueError("empty mount in section header")
            section = (mount, {})
    finish(section)
    return {"name": contract["name"], "result": {"records": records}}

