from pathlib import Path

_KEYS = ("device", "mount", "fstype", "options")


def _check_contract(contract, payloads):
    if not isinstance(contract, dict):
        raise ValueError("contract must be object")
    for key in ("name", "inputs"):
        if key not in contract:
            raise ValueError("contract missing field: %s" % key)
    if not isinstance(contract["name"], str):
        raise ValueError("contract name must be string")
    if not isinstance(contract["inputs"], list):
        raise ValueError("contract inputs must be list")
    if len(payloads) != len(contract["inputs"]):
        raise ValueError("payload count mismatch")


def _split_source(payload, contract_input):
    if isinstance(payload, dict) and set(payload.keys()) == {"name", "result"}:
        name = payload["name"]
        if not isinstance(name, str) or not name:
            raise ValueError("bad source name")
        return name, payload["result"]
    if isinstance(contract_input, str) and contract_input:
        return Path(contract_input).stem, payload
    return "", payload


def _records(data):
    if not isinstance(data, dict) or "records" not in data:
        raise ValueError("missing records")
    entries = data["records"]
    if not isinstance(entries, list):
        raise ValueError("records must be list")
    records = []
    for entry in entries:
        if not isinstance(entry, dict):
            raise ValueError("record must be object")
        rec = {}
        for key in _KEYS:
            if key not in entry or not isinstance(entry[key], str):
                raise ValueError("bad record field: %s" % key)
            rec[key] = entry[key]
        records.append(rec)
    return records


def transform(payloads, contract):
    _check_contract(contract, payloads)
    sources = []
    for payload, contract_input in zip(payloads, contract["inputs"]):
        name, data = _split_source(payload, contract_input)
        sources.append((name, _records(data)))
    grouped = {}
    for name, records in sources:
        for rec in records:
            grouped.setdefault(rec["mount"], []).append((name, rec))
    out_records = []
    conflicts = []
    for mount in sorted(grouped):
        entries = grouped[mount]
        winner_name, winner = entries[0]
        out_records.append({
            "device": winner["device"],
            "mount": mount,
            "fstype": winner["fstype"],
            "options": winner["options"],
            "source": winner_name,
        })
        signatures = {(rec["device"], rec["fstype"], rec["options"]) for _, rec in entries}
        if len(signatures) > 1:
            conflicts.append({
                "mount": mount,
                "evidence": [
                    {
                        "device": rec["device"],
                        "mount": mount,
                        "fstype": rec["fstype"],
                        "options": rec["options"],
                        "source": name,
                    }
                    for name, rec in entries
                ],
            })
    return {"name": contract["name"], "result": {"records": out_records, "conflicts": conflicts}}

