import json
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def fail(message):
    print("run_all: %s" % message, file=sys.stderr)
    sys.exit(1)


def load_contracts():
    contracts = []
    for cp in sorted(ROOT.rglob("contract.json")):
        parts = cp.relative_to(ROOT).parts
        if "outputs" in parts or "__pycache__" in parts:
            continue
        contracts.append(cp)
    if not contracts:
        fail("no contracts found")
    components = {}
    for cp in contracts:
        try:
            contract = json.loads(cp.read_text(encoding="utf-8"))
        except Exception as exc:
            fail("cannot read contract %s: %s" % (cp, exc))
        if not isinstance(contract, dict):
            fail("contract must be object: %s" % cp)
        for key in ("name", "inputs", "output"):
            if key not in contract:
                fail("contract missing field %s: %s" % (key, cp))
        if not isinstance(contract["name"], str) or not contract["name"]:
            fail("bad contract name: %s" % cp)
        if not isinstance(contract["inputs"], list) or not isinstance(contract["output"], str):
            fail("bad contract fields: %s" % cp)
        if contract["name"] in components:
            fail("duplicate component name: %s" % contract["name"])
        components[contract["name"]] = (cp, contract)
    return components


def main():
    components = load_contracts()
    producer = {}
    for name, (_, contract) in components.items():
        output = contract["output"]
        if output in producer:
            fail("duplicate output path: %s" % output)
        producer[output] = name
    deps = {name: set() for name in components}
    for name, (_, contract) in components.items():
        for inp in contract["inputs"]:
            if inp in producer:
                deps[name].add(producer[inp])
            elif not (ROOT / inp).is_file():
                fail("missing dependency %s for component %s" % (inp, name))
    order = []
    remaining = {name: set(d) for name, d in deps.items()}
    while remaining:
        ready = sorted(name for name, d in remaining.items() if not d)
        if not ready:
            fail("dependency cycle among: %s" % ", ".join(sorted(remaining)))
        for name in ready:
            order.append(name)
            del remaining[name]
        for d in remaining.values():
            d.difference_update(ready)
    for name in order:
        cp = components[name][0]
        proc = subprocess.run([sys.executable, str(cp.with_name("render.py"))], cwd=ROOT)
        if proc.returncode != 0:
            fail("component %s failed" % name)
    for script in ("integrate.py", "final_report.py"):
        proc = subprocess.run([sys.executable, str(ROOT / script)], cwd=ROOT)
        if proc.returncode != 0:
            fail("%s failed" % script)


if __name__ == "__main__":
    main()

import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent
_FALSE_KEYS = ("complete", "checkout", "committed", "ok")
_NONEMPTY_KEYS = ("unavailable", "missing", "conflicts", "unreachable")


def _attention(components):
    names = set()
    for name, result in components.items():
        if not isinstance(result, dict):
            continue
        if result.get("blocked") is True:
            names.add(name)
        for key in _FALSE_KEYS:
            if key in result and result[key] is False:
                names.add(name)
        for key in _NONEMPTY_KEYS:
            value = result.get(key)
            if isinstance(value, (list, dict, str, tuple, set)) and len(value) > 0:
                names.add(name)
    return sorted(names)


def build_report(core):
    if not isinstance(core, dict) or not isinstance(core.get("components"), dict):
        raise ValueError("bad core manifest")
    components = core["components"]
    serialized = json.dumps(
        core, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False
    ).encode("utf-8")
    digest = hashlib.sha256(serialized).hexdigest()
    return {
        "title": "三种挂载格式的离线事实归并",
        "component_count": len(components),
        "sha256": digest,
        "attention": _attention(components),
    }


def main():
    core = json.loads((ROOT / "outputs" / "core_manifest.json").read_text(encoding="utf-8"))
    report = build_report(core)
    out = ROOT / "outputs" / "final_report.json"
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(
        json.dumps(report, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()

